B\n\napp-layout.js: fix settings gear link /dashboard → /dashboard/settings","tree":{"sha":"2db686c8f3048007cbfaf2b3885b7d50f263f58d","url":"https://api.github.com/repos/Abivin-IT/vRoute-Open/git/trees/2db686c8f3048007cbfaf2b3885b7d50f263f58d"},"url":"https://api.github.com/repos/Abivin-IT/vRoute-Open/git/commits/3fd1fbbe2f1b55b67837da9b239ae2243fa5b752","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/5010238?v=4","events_url":"https://api.github.com/users/phamnamlong/events{/privacy}","followers_url":"https://api.github.com/users/phamnamlong/followers","following_url":"https://api.github.com/users/phamnamlong/following{/other_user}","gists_url":"https://api.github.com/users/phamnamlong/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/phamnamlong","id":5010238,"login":"phamnamlong","node_id":"MDQ6VXNlcjUwMTAyMzg=","organizations_url":"https://api.github.com/users/phamnamlong/orgs","received_events_url":"https://api.github.com/users/phamnamlong/received_events","repos_url":"https://api.github.com/users/phamnamlong/repos","site_admin":false,"starred_url":"https://api.github.com/users/phamnamlong/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/phamnamlong/subscriptions","type":"User","url":"https://api.github.com/users/phamnamlong","user_view_type":"public"},"html_url":"https://github.com/Abivin-IT/vRoute-Open/commit/3fd1fbbe2f1b55b67837da9b239ae2243fa5b752","node_id":"C_kwDODzvt3toAKDNmZDFmYmJlMmYxYjU1YjY3ODM3ZGE5YjIzOWFlMjI0M2ZhNWI3NTI","parents":[{"html_url":"https://github.com/Abivin-IT/vRoute-Open/commit/143b6ab8c34943c65c6c4fc261605e5da36833d5","sha":"143b6ab8c34943c65c6c4fc261605e5da36833d5","url":"https://api.github.com/repos/Abivin-IT/vRoute-Open/commits/143b6ab8c34943c65c6c4fc261605e5da36833d5"}],"sha":"3fd1fbbe2f1b55b67837da9b239ae2243fa5b752","url":"https://api.github.com/repos/Abivin-IT/vRout